package com.crm.department.controller;
import com.crm.department.entity.Department; import com.crm.department.repository.DepartmentRepository; import com.crm.common.response.ApiResponse; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/departments") @RequiredArgsConstructor public class DepartmentController{private final DepartmentRepository repo;
@GetMapping public ApiResponse<List<Department>> all(@RequestParam(required=false) Long companyId,@RequestParam(required=false) Long branchId){List<Department> d=branchId!=null?repo.findByBranchId(branchId):(companyId!=null?repo.findByCompanyId(companyId):repo.findAll());return ApiResponse.<List<Department>>builder().success(true).message("Departments fetched").data(d).build();}
@GetMapping("/{id}") public ApiResponse<Department> get(@PathVariable Long id){return ApiResponse.<Department>builder().success(true).message("Department fetched").data(repo.findById(id).orElseThrow(()->new IllegalArgumentException("Department not found"))).build();}
@PostMapping @ResponseStatus(HttpStatus.CREATED) public ApiResponse<Department> create(@Valid @RequestBody Department d){if(repo.existsByCode(d.getCode()))throw new IllegalArgumentException("Department code already exists");return ApiResponse.<Department>builder().success(true).message("Department created").data(repo.save(d)).build();}
@PutMapping("/{id}") public ApiResponse<Department> update(@PathVariable Long id,@Valid @RequestBody Department d){Department x=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Department not found"));x.setName(d.getName());x.setCode(d.getCode());x.setCompanyId(d.getCompanyId());x.setBranchId(d.getBranchId());x.setDescription(d.getDescription());x.setActive(d.isActive());return ApiResponse.<Department>builder().success(true).message("Department updated").data(repo.save(x)).build();}
@DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable Long id){repo.deleteById(id);return ApiResponse.<Void>builder().success(true).message("Department deleted").build();}}